-- Phase 7 (approved by the owner on 2026-11-14): locations, stock receipts,
-- transfer approval and discrepancies, stock counts. Additive, except the
-- transfer over-receipt CHECK at the end (approved separately; 0 rows).
-- Generated by prisma migrate diff, then the guard rails below added by hand.

-- AlterTable
ALTER TABLE "InventoryMovement" ADD COLUMN     "onHandAfter" INTEGER,
ADD COLUMN     "reasonCode" TEXT,
ADD COLUMN     "reservedAfter" INTEGER,
ADD COLUMN     "unitCostPoisha" INTEGER;

-- AlterTable
ALTER TABLE "Location" ADD COLUMN     "district" TEXT,
ADD COLUMN     "division" TEXT,
ADD COLUMN     "isSample" BOOLEAN NOT NULL DEFAULT false,
ADD COLUMN     "thana" TEXT;

-- AlterTable
ALTER TABLE "StockCount" ADD COLUMN     "appliedByUserId" TEXT,
ADD COLUMN     "cancelledAt" TIMESTAMP(3),
ADD COLUMN     "categoryId" TEXT,
ADD COLUMN     "submittedAt" TIMESTAMP(3),
ADD COLUMN     "submittedByUserId" TEXT,
ALTER COLUMN "status" SET DEFAULT 'IN_PROGRESS';

-- AlterTable
ALTER TABLE "StockCountItem" ADD COLUMN     "countedAt" TIMESTAMP(3),
ADD COLUMN     "movementsSinceSnapshot" INTEGER,
ADD COLUMN     "snapshotAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP;

-- AlterTable
ALTER TABLE "StockTransfer" ADD COLUMN     "approvedAt" TIMESTAMP(3),
ADD COLUMN     "approvedByUserId" TEXT,
ADD COLUMN     "cancelReason" TEXT,
ADD COLUMN     "cancelledByUserId" TEXT;

-- AlterTable
ALTER TABLE "StockTransferItem" ADD COLUMN     "discrepancyReason" "TransferDiscrepancyReason";

-- CreateTable
CREATE TABLE "StockReceipt" (
    "id" TEXT NOT NULL,
    "reference" TEXT NOT NULL,
    "kind" "StockReceiptKind" NOT NULL,
    "source" "StockReceiptSource" NOT NULL,
    "locationId" TEXT,
    "supplierReference" TEXT,
    "note" TEXT,
    "fileName" TEXT,
    "fileHash" TEXT,
    "rowCount" INTEGER NOT NULL,
    "totalQuantity" INTEGER NOT NULL,
    "createdByUserId" TEXT,
    "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,

    CONSTRAINT "StockReceipt_pkey" PRIMARY KEY ("id")
);

-- CreateIndex
CREATE UNIQUE INDEX "StockReceipt_reference_key" ON "StockReceipt"("reference");

-- CreateIndex
CREATE INDEX "StockReceipt_fileHash_idx" ON "StockReceipt"("fileHash");

-- CreateIndex
CREATE INDEX "StockReceipt_createdAt_idx" ON "StockReceipt"("createdAt");

-- AddForeignKey
ALTER TABLE "StockTransfer" ADD CONSTRAINT "StockTransfer_approvedByUserId_fkey" FOREIGN KEY ("approvedByUserId") REFERENCES "User"("id") ON DELETE SET NULL ON UPDATE CASCADE;

-- AddForeignKey
ALTER TABLE "StockTransfer" ADD CONSTRAINT "StockTransfer_receivedByUserId_fkey" FOREIGN KEY ("receivedByUserId") REFERENCES "User"("id") ON DELETE SET NULL ON UPDATE CASCADE;

-- AddForeignKey
ALTER TABLE "StockTransfer" ADD CONSTRAINT "StockTransfer_cancelledByUserId_fkey" FOREIGN KEY ("cancelledByUserId") REFERENCES "User"("id") ON DELETE SET NULL ON UPDATE CASCADE;

-- AddForeignKey
ALTER TABLE "StockCount" ADD CONSTRAINT "StockCount_categoryId_fkey" FOREIGN KEY ("categoryId") REFERENCES "Category"("id") ON DELETE SET NULL ON UPDATE CASCADE;

-- AddForeignKey
ALTER TABLE "StockCount" ADD CONSTRAINT "StockCount_submittedByUserId_fkey" FOREIGN KEY ("submittedByUserId") REFERENCES "User"("id") ON DELETE SET NULL ON UPDATE CASCADE;

-- AddForeignKey
ALTER TABLE "StockCount" ADD CONSTRAINT "StockCount_appliedByUserId_fkey" FOREIGN KEY ("appliedByUserId") REFERENCES "User"("id") ON DELETE SET NULL ON UPDATE CASCADE;

-- AddForeignKey
ALTER TABLE "StockReceipt" ADD CONSTRAINT "StockReceipt_locationId_fkey" FOREIGN KEY ("locationId") REFERENCES "Location"("id") ON DELETE RESTRICT ON UPDATE CASCADE;

-- AddForeignKey
ALTER TABLE "StockReceipt" ADD CONSTRAINT "StockReceipt_createdByUserId_fkey" FOREIGN KEY ("createdByUserId") REFERENCES "User"("id") ON DELETE SET NULL ON UPDATE CASCADE;


-- ---------------------------------------------------------------------------
-- Guard rails Prisma cannot express. Existing rows were checked read-only
-- before this migration: every location code matches and the one default
-- online location is online and active.
-- ---------------------------------------------------------------------------

-- Location codes: capital letters and digits in hyphen-separated groups (WH-01).
ALTER TABLE "Location"
  ADD CONSTRAINT "Location_code_format" CHECK ("code" ~ '^[A-Z0-9]+(-[A-Z0-9]+)*$' AND length("code") <= 20),
  -- The default online location must itself be online, active and not deleted.
  ADD CONSTRAINT "Location_default_is_online_and_active" CHECK (
    NOT "isDefaultOnlineFulfillment"
    OR ("isOnlineFulfillment" AND "isActive" AND "deletedAt" IS NULL)
  );

-- Stock after a movement can never be negative; costs are never negative.
ALTER TABLE "InventoryMovement"
  ADD CONSTRAINT "InventoryMovement_after_nonnegative" CHECK (
    ("onHandAfter" IS NULL OR "onHandAfter" >= 0)
    AND ("reservedAfter" IS NULL OR "reservedAfter" >= 0)
  ),
  ADD CONSTRAINT "InventoryMovement_unitCost_nonnegative"
    CHECK ("unitCostPoisha" IS NULL OR "unitCostPoisha" >= 0);

ALTER TABLE "StockReceipt"
  ADD CONSTRAINT "StockReceipt_totals_valid" CHECK ("rowCount" >= 0 AND "totalQuantity" >= 0);

ALTER TABLE "StockCountItem"
  ADD CONSTRAINT "StockCountItem_quantities_valid" CHECK (
    "systemQty" >= 0 AND ("countedQty" IS NULL OR "countedQty" >= 0)
  );

-- One open (in progress or submitted) stock count per location at a time.
CREATE UNIQUE INDEX "StockCount_one_open_per_location"
  ON "StockCount" ("locationId")
  WHERE "status" IN ('IN_PROGRESS', 'SUBMITTED');

-- Receipt references (RCV-2026-0001), like transfers and counts.
CREATE SEQUENCE IF NOT EXISTS "stock_receipt_reference_seq" AS BIGINT START WITH 1 INCREMENT BY 1;

-- Movement history and the ledger check read by type and reference.
CREATE INDEX "StockTransferItem_variantId_idx" ON "StockTransferItem" ("variantId");

-- ---------------------------------------------------------------------------
-- Over-receipt (owner decision 2026-11-14): a destination may receive more
-- than was sent; the excess is recorded as an EXCESS discrepancy. The old
-- constraint capped quantityReceived at quantitySent. StockTransferItem had
-- 0 rows when this was written.
-- ---------------------------------------------------------------------------
ALTER TABLE "StockTransferItem" DROP CONSTRAINT "StockTransferItem_quantityReceived_valid";
ALTER TABLE "StockTransferItem" ADD CONSTRAINT "StockTransferItem_quantityReceived_nonnegative"
  CHECK ("quantityReceived" IS NULL OR "quantityReceived" >= 0);
